import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"Host API v1alpha3","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/v1alpha3.md","filePath":"spec/host-api/v1alpha3.md"}'),n={name:"spec/host-api/v1alpha3.md"};function r(s,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="host-api-v1alpha3" tabindex="-1">Host API v1alpha3 <a class="header-anchor" href="#host-api-v1alpha3" aria-label="Permalink to &quot;Host API v1alpha3&quot;">​</a></h1><p><code>forms.takoform.com/v1alpha3</code> is the current Host API lane (<a href="./../decisions/0013-v1alpha3-lane-ships-in-provider-v2-1.html">decision 0013</a>). It carries namespaced FormRef groups, UID/generation/revision resource identity, long-running Operations, content-addressed artifact upload, and Host Support Profiles. The retained v1alpha2 contract in <a href="./"><code>README.md</code></a> continues to govern the frozen provider-v2 lane; rules stated there and not changed here (space identity, I-JSON raw-first decoding, idempotency-key namespacing, replay fingerprinting, same-origin endpoint negotiation) apply to this lane unchanged.</p><p>The wire schema is <a href="/schemas/v1alpha3/host-api-wire.schema.json"><code>../schemas/host-api-wire-v1alpha3.schema.json</code></a>; the machine operation table is <a href="operations-v1alpha3.json"><code>operations-v1alpha3.json</code></a>.</p><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><p><code>GET /.well-known/takoform/v1alpha3</code> returns a document validating against <a href="/schemas/v1alpha3/host-discovery.schema.json"><code>../schemas/host-discovery-v1alpha3.schema.json</code></a>: <code>api_versions</code> is exactly <code>[&quot;forms.takoform.com/v1alpha3&quot;]</code>; the features <code>service_forms</code>, <code>exact_form_ref</code>, <code>optimistic_concurrency</code>, <code>idempotent_lifecycle</code>, <code>operations</code>, <code>artifact_upload</code>, and <code>support_profiles</code> are all required and true; <code>endpoints.api</code> is same-origin with path <code>/apis/forms.takoform.com/v1alpha3</code>. Each lane has its own discovery path; a v1alpha2 client can never select this lane accidentally.</p><h2 id="resource-identity" tabindex="-1">Resource identity <a class="header-anchor" href="#resource-identity" aria-label="Permalink to &quot;Resource identity&quot;">​</a></h2><ul><li><code>metadata.name</code> is the only name; Form desired schemas do not carry a <code>name</code> field.</li><li><code>metadata.uid</code> is host-issued and immutable. Delete followed by re-create of the same name yields a new UID. A client MAY fence any mutation with <code>expectedUid</code>; mismatch fails <code>uid_mismatch</code> (409).</li><li><code>metadata.generation</code> increments only when the portable desired spec changes. Desired-state mutations fence on the expected generation (<code>Takoform-Expected-Generation</code> header or <code>expectedGeneration</code> body field); a stale fence fails <code>generation_conflict</code> (412).</li><li><code>metadata.revision</code> increments whenever the representation — including status, conditions, and outputs — changes. The strong ETag is the quoted revision; <code>If-Match</code> fences on it and a stale value fails <code>revision_conflict</code> (412).</li><li>A host that renders any part of a representation from OTHER resources MUST advance that resource&#39;s <code>metadata.revision</code> when the rendering changes, and MUST NOT move its <code>metadata.generation</code>: no desired spec changed. This lane has two such renderings — relation drift and Worker readiness — so creating, re-weighting, or deleting a <code>WorkerDeployment</code> moves the revision of the <code>ModuleWorker</code> whose readiness follows it, and a target that is deleted or replaced moves the revision of every source pinned to it. Serving the changed representation under the old revision would make the ETag a validator that reports &quot;unchanged&quot; about a change, and <code>If-Match</code> a fence on a representation the client never saw. After an accepted mutation a host recomputes the rendering of every resource that mutation can affect and advances only those that actually changed, so an idempotent re-apply moves nothing anywhere. This is a required conformance check (<code>dependent-revision-advances-with-rendering</code>), and it is decided by <a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>.</li><li><code>status.observedGeneration</code> names the desired generation the status reflects; <code>status.conditions</code> uses the closed types <code>Ready</code>, <code>Reconciling</code>, <code>Degraded</code>, <code>Drifted</code>, <code>Blocked</code>, <code>Deleting</code> with closed portable reasons and an optional non-portable <code>hostReason</code>.</li><li>The Form semantic identity is the exact FormRef. The package digest used at installation is audit evidence (<code>form.packageDigest</code>, optional in responses); it never enters queries, fences, or state identity, and a host that installed the same FormRef from a different legitimate package MUST read and delete the same resources.</li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Endpoints under <code>/apis/forms.takoform.com/v1alpha3</code>, keyed by group and kind so one kind name can exist in many groups:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET    {api}/forms?space&amp;group&amp;kind&amp;definitionVersion&amp;schemaDigest</span></span>
<span class="line"><span>GET    {api}/form-definitions/{group}/{kind}?…</span></span>
<span class="line"><span>POST   {api}/resources/validate         diagnostics only, no mutation, no digest</span></span>
<span class="line"><span>POST   {api}/resources/prepare          short-lived prepare digest for one exact spec</span></span>
<span class="line"><span>PUT    {api}/resources/{group}/{kind}/{name}    apply; carries review.prepareDigest</span></span>
<span class="line"><span>GET    {api}/resources/{group}/{kind}/{name}</span></span>
<span class="line"><span>POST   {api}/resources/{group}/{kind}/{name}/import</span></span>
<span class="line"><span>POST   {api}/resources/{group}/{kind}/{name}/observe</span></span>
<span class="line"><span>DELETE {api}/resources/{group}/{kind}/{name}</span></span></code></pre></div><p><code>observe</code> is the lane&#39;s only fenced read-only re-observation. There is no <code>refresh</code> operation: v1alpha2 carried both under one contract, which meant two spellings of one behavior and therefore two ways for hosts to differ. A v1alpha3 Form never declares the <code>refresh</code> capability and a v1alpha3 host serves no <code>/refresh</code> route.</p><p><code>validate</code> reports diagnostics without mutating and without minting a digest; a client MUST NOT describe provider apply-time preparation as &quot;reviewed in plan&quot;. <code>prepare</code> binds the exact spec, identity, and fences to a <code>prepareDigest</code> the way v1alpha2 <code>preview</code> binds a plan digest; substitution after prepare fails <code>invalid_argument</code> before mutation.</p><p>Role rules are wire-enforced: an update to a <code>revision</code>-role resource fails <code>invalid_argument</code>; deleting a resource any live relation references fails <code>dependency_in_use</code> (409); deleting a <code>deployment</code>-role resource any live dependent needs fails the same way (<a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>); a resource protected by policy fails <code>deletion_protected</code> (409).</p><h2 id="cross-resource-relations" tabindex="-1">Cross-resource relations <a class="header-anchor" href="#cross-resource-relations" aria-label="Permalink to &quot;Cross-resource relations&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>.</p><p>A <strong>relation</strong> is one reference from a resource&#39;s desired spec to another resource. Its wire shape is the closed three-member object</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EdgeKVNamespace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>where <code>apiVersion</code> and <code>kind</code> are <code>const</code> in the referring Form&#39;s <code>desiredSchema</code> and <code>name</code> follows the portable resource-name grammar. Both constants are required. A reference carrying only <code>{kind, name}</code> cannot address two Form Families at once and forces a host to guess which installed Form a bare kind means; a group-qualified reference makes the target Form exact.</p><p>Relations are <strong>derived from the Form Definition&#39;s <code>desiredSchema</code>, never declared</strong>. Every reference already states its target group and kind as schema constants, so a separate relation list on the Definition would be a second source of truth for facts the schema already carries — and the published Form Definition schema admits no such member (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>). A host derives the relation set from the same <code>desiredSchema</code> it serves: every closed object that requires exactly <code>apiVersion</code>, <code>kind</code>, and <code>name</code> with the first two <code>const</code> is a relation, identified by its JSON Pointer with <code>*</code> standing for an array element (<code>/worker</code>, <code>/versions/*/workerVersion</code>, <code>/kvBindings/*/resource</code>). A binding-list property additionally carries the <code>x-takoform-binding</code> annotation naming the Binding contract that governs the references inside it; the exact digest-bound BindingRef is the Definition&#39;s own <code>acceptedBindings</code> entry of that name.</p><h3 id="resolution-and-uid-pinning" tabindex="-1">Resolution and UID pinning <a class="header-anchor" href="#resolution-and-uid-pinning" aria-label="Permalink to &quot;Resolution and UID pinning&quot;">​</a></h3><p>On <code>apply</code> and <code>import</code>, for every derived relation present in the materialized spec, a host MUST, before any mutation (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>):</p><ul><li>resolve <code>(space, apiVersion, kind, name)</code> to a stored resource. Absent fails <code>resource_not_found</code> (404) and the message MUST name the relation pointer. Cross-space references are unrepresentable — a reference carries no space.</li><li>verify that the resolved resource&#39;s Form has exactly the referenced group and kind, failing <code>invalid_argument</code> (400) on mismatch. A well-formed spec cannot reach this, because the schema pins both constants; a host that resolved by name alone can, and must refuse rather than bind the wrong Form.</li><li>verify the binding contract when the relation is a binding (below).</li><li>record the resolution as <code>{pointer, relation, targetAPIVersion, targetKind, targetName, targetUID, bindingRef?}</code> alongside the resource, where <code>pointer</code> is the concrete instance pointer and <code>relation</code> is the derived pointer it came from.</li></ul><p>A host MUST store the <strong>target UID</strong>, not only the name. A name is a label the client chose and can reuse; the UID is the identity of one incarnation.</p><h3 id="incarnation-change" tabindex="-1">Incarnation change <a class="header-anchor" href="#incarnation-change" aria-label="Permalink to &quot;Incarnation change&quot;">​</a></h3><p>When a resource is read or observed and a stored relation&#39;s target now resolves to a <em>different</em> UID, or to nothing, the source reports <code>Ready=False</code> with</p><ul><li><code>ExternalChange</code> — the target name resolves to a different incarnation;</li><li><code>DependencyMissing</code> — the target no longer exists;</li></ul><p>and a <code>hostReason</code> naming the relation pointer and both UIDs. A host MUST NOT re-bind the relation automatically: re-resolving the name would make a delete and re-create of the target invisible and silently point the source at a resource its author never named. The source stays pinned until it is re-applied, and re-reading it does not heal the condition.</p><h3 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h3><p>The remedy is an apply, and it MUST stay reachable (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>).</p><ul><li><strong>What the host reports.</strong> The condition above, on <code>read</code> and <code>observe</code>, for as long as the stored relation does not resolve to its pinned UID. Reporting it is not an error outcome: the resource is still readable, still deletable, and still carries its desired spec.</li><li><strong>What re-pins.</strong> Every ACCEPTED mutation re-resolves every relation and stores the UIDs it resolved to, including a <code>apply</code> whose spec is byte-identical to the stored one. Re-pinning is host-owned bookkeeping, not desired state: it MUST NOT move <code>metadata.generation</code>, and it moves <code>metadata.revision</code> exactly when it changes the representation the host serves — which it does, because the Ready condition stops reporting the drift. A second identical apply then moves nothing at all.</li><li><strong>What a client must do.</strong> Report the break without failing the read, and offer an apply. A client that fails its refresh on this condition removes its own remedy, because the plan that repairs the resource is computed from the refreshed state. A Form that declares <code>update</code> recovers with a spec-identical apply. A Form that declares none — every <code>revision</code>-role Form — has no such apply at all: a host refuses every apply to the existing resource, so its only recovery is REPLACEMENT, and a client MUST plan one. A <code>DependencyMissing</code> target must exist again before either apply can succeed.</li></ul><h3 id="dependency-protection" tabindex="-1">Dependency protection <a class="header-anchor" href="#dependency-protection" aria-label="Permalink to &quot;Dependency protection&quot;">​</a></h3><p>Deleting a resource that any stored relation references by UID fails <code>dependency_in_use</code> (409). This covers every relation, not only typed bindings: a Worker Bundle a Worker Version executes, a Worker Version a Worker Deployment weights, a Module Worker an attachment activates, a queue a consumer drains, and a dead-letter queue are all live dependencies. A resource that references itself does not block its own deletion. An accepted (202) delete re-runs the scan at commit time, so a resource that acquired a holder while the operation was pending survives.</p><h3 id="binding-verification" tabindex="-1">Binding verification <a class="header-anchor" href="#binding-verification" aria-label="Permalink to &quot;Binding verification&quot;">​</a></h3><p>A binding relation is verified, never assumed. Before any mutation a host MUST check, in this order:</p><ol><li>the source Form Definition&#39;s <code>acceptedBindings</code> carries the Binding contract the desired schema annotates — otherwise <code>invalid_argument</code> (400);</li><li>the host has installed that contract at exactly the accepted <code>schemaDigest</code> — otherwise <code>unsupported_capability</code> (422), because the capability itself is unavailable rather than the request malformed;</li><li>the source Form&#39;s <code>role</code> equals the Binding Definition&#39;s <code>sourceRole</code> — otherwise <code>invalid_argument</code> (400);</li><li>the resolved target&#39;s exact Form (group and kind) appears in the Binding Definition&#39;s <code>allowedTargetForms</code> — otherwise <code>invalid_argument</code> (400);</li><li>the target Form&#39;s Definition declares the Binding&#39;s <code>targetInterface</code> in <code>providedInterfaces</code> — otherwise <code>invalid_argument</code> (400). A binding projects an Interface, so a target that provides none cannot be bound;</li><li>source and target share a space, which the wire guarantees: a reference carries no space member.</li></ol><p>Rules 3 through 5 are about the target or holder the client chose and are therefore argument failures; rule 2 is about what this host can do at all.</p><h2 id="the-worker-aggregate" tabindex="-1">The Worker aggregate <a class="header-anchor" href="#the-worker-aggregate" aria-label="Permalink to &quot;The Worker aggregate&quot;">​</a></h2><p>The rules of this section are decided by <a href="./../decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>. They are semantics a desired-state schema cannot express — a schema cannot count the deployments pointing at one worker, read the <code>/worker</code> relation of a version it does not contain, add weights, know which handlers a referenced version exports, or reach across sibling properties — so they live in the host under <a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a> and are proven by required conformance checks.</p><p>A <strong>Worker aggregate</strong> is one <code>ModuleWorker</code> incarnation, the Worker Versions pinned to it, the one Worker Deployment governing its traffic, and everything activated against it. Every rule below is decided against the UID the reference RESOLVED to, never against the worker name a spec spells.</p><h3 id="one-active-deployment" tabindex="-1">One active deployment <a class="header-anchor" href="#one-active-deployment" aria-label="Permalink to &quot;One active deployment&quot;">​</a></h3><p>A <code>WorkerDeployment</code> whose resolved <code>/worker</code> UID already has one fails <code>invalid_argument</code> (400) before any mutation, on <code>apply</code> and on <code>import</code> alike. Re-applying a worker&#39;s own deployment is not a second one. Traffic moves by re-weighting the deployment a worker already has, which is what makes rollback a re-weighting rather than a mutation of a revision.</p><h3 id="deployment-integrity" tabindex="-1">Deployment integrity <a class="header-anchor" href="#deployment-integrity" aria-label="Permalink to &quot;Deployment integrity&quot;">​</a></h3><p>Before any mutation a host MUST refuse a deployment whose <code>versions[]</code></p><ul><li>weights a <code>WorkerVersion</code> whose stored <code>/worker</code> relation targets a different worker UID;</li><li>names one <code>WorkerVersion</code> twice, by resolved UID — <code>uniqueItems</code> rejects a duplicated whole entry, so one version split across two different weights is schema-valid and still says two things about one revision;</li><li>carries weights that do not sum to exactly 10000 basis points;</li><li>weights a version that is not Ready, or that an accepted delete is already removing.</li></ul><p>Each is <code>invalid_argument</code> (400): the request is well formed but states something untrue about what will run.</p><h3 id="attachment-gate" tabindex="-1">Attachment gate <a class="header-anchor" href="#attachment-gate" aria-label="Permalink to &quot;Attachment gate&quot;">​</a></h3><p>Inward activation is admitted against the worker&#39;s ACTIVE DEPLOYMENT, not against any stored version:</p><table tabindex="0"><thead><tr><th>Attachment</th><th>Required module handler</th></tr></thead><tbody><tr><td><code>WorkerCustomDomain</code></td><td><code>fetch</code></td></tr><tr><td><code>WorkerCronTrigger</code></td><td><code>scheduled</code></td></tr><tr><td><code>QueueConsumer</code></td><td><code>queue</code></td></tr></tbody></table><p>EVERY version the deployment weights MUST export that handler, because a request served by any weighted version has to find it. An absent deployment, or a weighted version that does not export the handler, fails <code>unsupported_capability</code> (422) before any mutation and the message names what is missing. A stored version is a history entry, not a running one: gating on it would admit a cron trigger against code no deployment selects.</p><h3 id="reverse-validation-and-deletion" tabindex="-1">Reverse validation and deletion <a class="header-anchor" href="#reverse-validation-and-deletion" aria-label="Permalink to &quot;Reverse validation and deletion&quot;">​</a></h3><p>The gate holds in both directions.</p><ul><li>An apply that would leave a live dependent unserved fails <code>unsupported_capability</code> (422) before any mutation. The dependents are a live <code>WorkerCustomDomain</code> (<code>fetch</code>), a live <code>WorkerCronTrigger</code> (<code>scheduled</code>), a live <code>QueueConsumer</code> (<code>queue</code>), and a live INBOUND service binding — another Form&#39;s <code>serviceBindings</code> entry targeting this worker — which requires <code>fetch</code>.</li><li>Deleting a <code>WorkerDeployment</code> while any of those four lives fails <code>dependency_in_use</code> (409). Nothing REFERENCES a deployment, so this is not the relation rule above; it is the same statement about a different edge. A host fails closed rather than degrading the dependents, and an accepted (202) delete re-runs the scan at commit time.</li></ul><h3 id="worker-readiness-and-inbound-service-bindings" tabindex="-1">Worker readiness and inbound service bindings <a class="header-anchor" href="#worker-readiness-and-inbound-service-bindings" aria-label="Permalink to &quot;Worker readiness and inbound service bindings&quot;">​</a></h3><p><code>worker.service</code> is provided by the <code>ModuleWorker</code> identity and answered by whatever its active deployment selects, so readiness is a claim about SERVICE:</p><ul><li><code>Ready=True</code> / <code>Available</code> only when the worker has an active deployment whose every weighted version exports <code>fetch</code>;</li><li><code>Ready=False</code> / <code>Provisioning</code> when it has no deployment;</li><li><code>Ready=False</code> / <code>UnsupportedCapability</code> when its deployment serves no <code>fetch</code>.</li></ul><p>Both false cases carry a <code>hostReason</code> naming the worker and what is missing. A <code>module-worker.service</code> binding to a worker in either state is refused at BIND time with <code>unsupported_capability</code> (422), rather than stored and reported not-Ready: a stored binding that projects nothing is a declared capability no host can keep.</p><p>The worker is not addressed by any of the mutations that move it between these three states, so this is a representation rendered from another resource: a host MUST advance the worker&#39;s <code>metadata.revision</code>, and MUST NOT move its <code>metadata.generation</code>, when a deployment change flips the condition (see <a href="#resource-identity">Resource identity</a>).</p><h3 id="the-environment-namespace-is-single" tabindex="-1">The environment namespace is single <a class="header-anchor" href="#the-environment-namespace-is-single" aria-label="Permalink to &quot;The environment namespace is single&quot;">​</a></h3><p>Within one <code>WorkerVersion</code>, <code>vars</code> keys, <code>requiredSensitiveVars</code> entries, and every binding <code>name</code> across every binding list are projected into ONE runtime environment object, so their union MUST be unique. A collision fails <code>invalid_argument</code> (400) before any mutation, and a client SHOULD refuse it at plan time so the author sees it without a round trip. The schema cannot state it: <code>uniqueItems</code> compares whole objects, so two bindings agreeing only on <code>name</code> are distinct, and no keyword relates a property&#39;s keys to a sibling array&#39;s element member. A host discovers the binding lists from the <code>x-takoform-binding</code> annotation the desired schema already carries.</p><h2 id="lifecycle-capabilities" tabindex="-1">Lifecycle capabilities <a class="header-anchor" href="#lifecycle-capabilities" aria-label="Permalink to &quot;Lifecycle capabilities&quot;">​</a></h2><p><code>lifecycleCapabilities</code> is a claim about what a host can actually be asked to do, so it is derived from the Form&#39;s own declared fields rather than from its role. The base set every Form declares is exactly <code>create</code>, <code>read</code>, <code>delete</code>, <code>import</code>, <code>observe</code>. <code>update</code> is added only when the Form has at least one mutable desired field — a field that is not immutable, on a Form whose role is not <code>revision</code>. A Form with no field at all, or whose every field is immutable, therefore declares no <code>update</code>.</p><p>The rule is enforced on the wire in both directions. A host MUST refuse a spec-CHANGING apply to an existing resource whose Form Definition omits <code>update</code>, failing <code>invalid_argument</code> before any mutation; a client MUST plan a replacement rather than an in-place change for such a Form.</p><h2 id="portable-defaults" tabindex="-1">Portable defaults <a class="header-anchor" href="#portable-defaults" aria-label="Permalink to &quot;Portable defaults&quot;">​</a></h2><p>An optional desired property carries its portable meaning in its own schema: the Form Definition declares a JSON Schema <code>default</code> on that property inside <code>desiredSchema</code>. That default is normative, not advisory.</p><p>A host MUST materialize every declared top-level default into the desired spec at the entry point of <code>validate</code>, <code>prepare</code>, <code>apply</code>, and <code>import</code> — before the spec is validated, digested, stored, or echoed. Materialization fills only absent properties; a property that is present keeps its written value, even when that value equals the default. It follows that:</p><ul><li>the effective spec IS the wire spec: there is no second, host-private document a client cannot see;</li><li><code>specDigest</code> is the digest of the MATERIALIZED spec;</li><li>omitting a defaulted property and writing its default are one desired state: same <code>specDigest</code>, same <code>metadata.generation</code>, no update;</li><li>a client that sends an unmaterialized spec MUST accept the materialized echo from <code>prepare</code>, <code>apply</code>, <code>import</code>, and <code>read</code> as its own desired state.</li></ul><p>An optional property with no declared default is only legitimate when its ABSENCE is itself the portable semantics, and the property&#39;s <code>description</code> must then state what the absent case does.</p><h2 id="long-running-operations" tabindex="-1">Long-running operations <a class="header-anchor" href="#long-running-operations" aria-label="Permalink to &quot;Long-running operations&quot;">​</a></h2><p>Create, update, delete, import, and artifact commit MAY return <code>202 Accepted</code> with an Operation envelope (<a href="/schemas/operations/v1alpha1/operation.schema.json"><code>../schemas/operation-v1alpha1.schema.json</code></a>) instead of the terminal representation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  {api}/operations/{id}</span></span>
<span class="line"><span>POST {api}/operations/{id}/cancel</span></span></code></pre></div><p>Clients poll with <code>Retry-After</code> when present, otherwise exponential backoff with full jitter, under an overall deadline. The contract guarantees only that an operation ID is stable, that the host keeps it addressable at <code>GET {api}/operations/{id}</code> while the operation record exists (afterwards the closed outcome is <code>operation_not_found</code>), and that a terminal operation replays its terminal state instead of re-executing. A client can resume across its own restart only if it persists the ID first; no shipped Takoform client persists one today, so a restart during a long operation currently means re-reading the resource, not resuming the operation. A terminal Operation carries exactly one of <code>result</code> or <code>error</code>. Cancel is honored only for safely stoppable operations; an already-terminal operation replays its terminal state. <code>operation_not_found</code> (404) and <code>operation_cancelled</code> (409) are the closed outcomes; <code>deadline_exceeded</code> (504) reports a host-side deadline.</p><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>The content-addressed upload API is <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>. The artifact endpoints share the lane&#39;s auth, idempotency, and error taxonomy.</p><p>The desired state of a bundle-shaped revision resource is the <strong>manifest digest and nothing else</strong>: the committed artifact manifest describes the bytes, so the manifest and the desired spec are never two spellings of the same facts. A host MUST therefore resolve the referenced manifest before it mutates anything, on apply and on import alike, and fail closed when</p><ul><li>the digest names no committed manifest — <code>artifact_missing</code> (404);</li><li>the stored manifest&#39;s RFC 8785 canonical digest differs from the referenced digest, its document is undecodable, or its <code>kind</code> is not the kind the Form requires — <code>artifact_invalid</code> (400);</li><li>the manifest violates any rule of <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>, including its per-kind exclusivity, its closed media types, and the host&#39;s published <code>limits</code> — <code>artifact_invalid</code> (400).</li></ul><p>A committed manifest and its blobs MUST remain readable while any resource references the manifest. Abandoning an unrelated upload session, or garbage-collecting staged blobs, MUST NOT make a referenced artifact unresolvable.</p><h2 id="support-profiles" tabindex="-1">Support profiles <a class="header-anchor" href="#support-profiles" aria-label="Permalink to &quot;Support profiles&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET {api}/support/forms</span></span>
<span class="line"><span>GET {api}/support/forms/{group}/{kind}/{definitionVersion}</span></span>
<span class="line"><span>GET {api}/support/interfaces/{name}/{version}</span></span>
<span class="line"><span>GET {api}/support/bindings/{name}/{version}</span></span></code></pre></div><p>Responses validate against <a href="/schemas/support/v1alpha1/host-support-profile.schema.json"><code>../schemas/host-support-profile-v1alpha1.schema.json</code></a>. A profile declares supported exact refs, closed capability subsets (<code>supportedEnums</code>), inclusive ranges (<code>supportedRanges</code>), supported binding contracts, and numeric limits. Price, SKU, region, quota, and commercial policy MUST NOT appear; those remain Service Offering data outside this API.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>The closed taxonomy extends v1alpha2 with <code>rate_limited</code> (429), <code>deadline_exceeded</code> (504), <code>operation_cancelled</code> (409), <code>operation_not_found</code> (404), <code>dependency_in_use</code> (409), <code>deletion_protected</code> (409), <code>artifact_missing</code> (404), <code>artifact_invalid</code> (400), <code>unsupported_capability</code> (422), <code>migration_required</code> (409), <code>uid_mismatch</code> (409), <code>revision_conflict</code> (412), and <code>generation_conflict</code> (412). Only <code>resource_busy</code>, <code>backend_unavailable</code>, <code>rate_limited</code>, and <code>deadline_exceeded</code> may be <code>retryable: true</code>; <code>Retry-After</code> is honored when present. The v1alpha2 codes <code>resource_version_conflict</code>, <code>interface_identity_ambiguous</code>, and <code>interface_instance_ambiguous</code> do not exist in this lane: version conflicts split into the revision/generation pair, and the v1alpha2 interface projection is replaced by exact Interface contracts (<a href="./../interface-contract/"><code>../interface-contract/</code></a>).</p>`,81)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
